with.command:
set -eu
printf '%s' "$TEXT" | REQUIRED="$REQUIRED" OPTIONAL="$OPTIONAL" python3 -c '
import json, os, re, subprocess, sys
try:
    asked = json.loads(sys.stdin.read())
except ValueError as error:
    sys.exit("the mandate is not one JSON object: %s" % error)
if not isinstance(asked, dict):
    sys.exit("the mandate is not one JSON object")
required = os.environ["REQUIRED"].split()
optional = json.loads(os.environ["OPTIONAL"])
missing = [key for key in required if not str(asked.get(key, "")).strip()]
if missing:
    sys.exit("the mandate does not name: " + ", ".join(missing))
unknown = sorted(set(asked) - set(required) - set(optional))
if unknown:
    sys.exit("the mandate names what this flow does not read: " + ", ".join(unknown))
out = {key: str(asked.get(key, default)) for key, default in optional.items()}
out.update({key: str(asked[key]) for key in required})
repo = out["repo"]
if not os.path.isabs(repo) or subprocess.run(["git", "-C", repo, "rev-parse", "--git-dir"], capture_output=True).returncode != 0:
    sys.exit("the repo is not an absolute path to a git tree: " + repo)
for key in ("branch", "base"):
    if key in out and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]*", out[key]):
        sys.exit("the %s is not a plain branch name: %s" % (key, out[key]))
for key in ("issue",):
    if key in out and not re.fullmatch(r"[0-9]+", out[key]):
        sys.exit("the issue is not a number: " + out[key])
if "version" in out and not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+(-[0-9A-Za-z.]+)?", out["version"]):
    sys.exit("the version is not MAJOR.MINOR.PATCH: " + out["version"])
if "forge_repo" in out and out["forge_repo"] and not re.fullmatch(r"[A-Za-z0-9._-]+/[A-Za-z0-9._-]+", out["forge_repo"]):
    sys.exit("the forge_repo is not owner/name: " + out["forge_repo"])
print(json.dumps(out))
'

set -eu
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    GH_TOKEN=$(gh auth token --user "$who") && [ -n "$GH_TOKEN" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    GH_TOKEN="$GH_TOKEN" gh "$@"
}
printf '{"login":"%s"}' "$forge_as"

set -eu
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "main:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
policy_now=$(cd "$REPO" && sailor policy) || { echo "the delivery policy could not be re-read from the trusted trunk" >&2; exit 1; }
policy_was=$(printf '%s' "$POLICY_READ" | python3 -c 'import json,sys; p=json.load(sys.stdin); print("merge: %s\npush: %s\nrelease: %s\n%s" % (p["merge"], p["push"], p["release"], p["read_from"]))')
[ "$policy_now" = "$policy_was" ] || { echo "the delivery policy changed since it was read: the authorization in flight no longer holds; run the flow again" >&2; exit 1; }
git fetch --quiet origin
[ "$(git rev-parse "refs/remotes/origin/$BASE")" = "$REF" ] || { echo "the remote $BASE moved off the candidate $REF since it was built" >&2; exit 1; }
set +e
if [ -n "$SCAN_BASE" ]; then "$REPO/scripts/privacy-scan.sh" "$REF" "$SCAN_BASE" >&2; else "$REPO/scripts/privacy-scan.sh" "$REF" >&2; fi
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan exited $code on $REF; nothing leaves" >&2; exit "$code"; }
printf '{"ref":"%s","privacy_exit":0}' "$REF"

set -eu
cd "$REPO"
trusted_scan() {
    git -C "$REPO" show "main:scripts/privacy-scan.sh" 2>/dev/null | cmp -s - "$REPO/scripts/privacy-scan.sh" || { echo "scripts/privacy-scan.sh in this tree differs from the one the trusted trunk commits: the gate refuses to judge with it" >&2; exit 2; }
}
trusted_scan
set +e
"$REPO/scripts/privacy-scan.sh" --text "$TEXT_FILE" >&2
code=$?
set -e
[ "$code" -eq 0 ] || { echo "publication gate: privacy-scan --text exited $code on $TEXT_FILE; the text does not leave" >&2; exit "$code"; }
sha=$(shasum -a 256 < "$TEXT_FILE" | awk '{ print $1 }')
printf '{"text_file":"%s","sha256":"%s","privacy_exit":0}' "$TEXT_FILE" "$sha"

set -eu
url=$(git -C "$REPO" remote get-url origin) || { echo "the tree has no origin remote" >&2; exit 1; }
set -- -C "$REPO"
case "$url" in
    /*|file://*) ;;
    http://*|https://*)
        push_as=$(git -C "$REPO" config --get sailor.pushAs) || { echo "sailor.pushAs is not declared on this tree: refusing to push with the machine's own credentials" >&2; exit 1; }
        helper='!f() { printf "%s\\n" username=x-access-token; printf "password=%s\\n" "$(gh auth token --user "'"$push_as"'")"; }; f'
        set -- -C "$REPO" -c credential.helper= -c "credential.helper=$helper" ;;
    *) echo "origin is $url: a push over it cannot be bound to sailor.pushAs, so this flow refuses it" >&2; exit 1 ;;
esac
if ! git -C "$REPO" rev-parse --verify --quiet "refs/tags/$TAG" >/dev/null; then
    git -C "$REPO" tag -a "$TAG" -m "$TAG" "$CANDIDATE"
fi
tagged=$(git -C "$REPO" rev-parse "refs/tags/$TAG^{commit}")
[ "$tagged" = "$CANDIDATE" ] || { echo "$TAG names $tagged, not $CANDIDATE" >&2; exit 1; }
object=$(git -C "$REPO" rev-parse "refs/tags/$TAG")
remote=$(git -C "$REPO" ls-remote origin "refs/tags/$TAG" | awk '{ print $1 }')
if [ -z "$remote" ]; then
    git "$@" push origin "refs/tags/$TAG:refs/tags/$TAG" >&2
    remote=$(git -C "$REPO" ls-remote origin "refs/tags/$TAG" | awk '{ print $1 }')
fi
[ "$remote" = "$object" ] || { echo "the remote $TAG reads ${remote:-nothing}, not $object" >&2; exit 1; }
printf '{"tag":"%s","commit":"%s"}' "$TAG" "$tagged"

set -eu
cd "$REPO"
forge_as=$(git -C "$REPO" config --get sailor.forgeAs) || { echo "sailor.forgeAs is not declared on this tree: refusing to act as the machine's active account" >&2; exit 1; }
[ -n "$forge_as" ] || { echo "sailor.forgeAs is empty on this tree: refusing to act as the machine's active account" >&2; exit 1; }
gh auth token --user "$forge_as" >/dev/null || { echo "no forge token for the declared account $forge_as" >&2; exit 1; }
[ -z "${FORGE_REPO:-}" ] || export GH_REPO="$FORGE_REPO"
# An empty --user or an empty GH_TOKEN makes gh answer as the machine's active account.
forge() {
    who=$(git -C "$REPO" config --get sailor.forgeAs) && [ -n "$who" ] || { echo "sailor.forgeAs vanished from this tree: refusing" >&2; exit 1; }
    GH_TOKEN=$(gh auth token --user "$who") && [ -n "$GH_TOKEN" ] || { echo "no forge token for $who: refusing" >&2; exit 1; }
    GH_TOKEN="$GH_TOKEN" gh "$@"
}
[ "$(shasum -a 256 < "$TEXT_FILE" | awk '{ print $1 }')" = "$TEXT_SHA" ] || { echo "$TEXT_FILE changed after the publication gate judged it: nothing leaves" >&2; exit 1; }
if ! forge release view "$TAG" --json tagName >/dev/null; then
    forge release create "$TAG" --verify-tag --title "$TAG" --notes-file "$TEXT_FILE" >&2
elif [ "$(forge release view "$TAG" --json isDraft --jq .isDraft)" = true ]; then
    forge release edit "$TAG" --draft=false >&2
fi
seen=$(forge release view "$TAG" --json tagName,isDraft,url --jq '[.tagName, .isDraft, .url] | @tsv')
[ "$(printf '%s' "$seen" | cut -f1)" = "$TAG" ] || { echo "the host has no release for $TAG" >&2; exit 1; }
[ "$(printf '%s' "$seen" | cut -f2)" = false ] || { echo "the release $TAG is still a draft" >&2; exit 1; }
printf '{"tag":"%s","url":"%s"}' "$TAG" "$(printf '%s' "$seen" | cut -f3)"
